-- 0005: payments & billing. Money = bigint minor units only.
create table public.payment_transactions (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, appointment_id uuid references public.appointments(id) on delete set null, provider public.payment_provider not null default 'manual', provider_ref text, provider_event_id text, amount_minor bigint not null check (amount_minor >= 0), currency text not null default 'BDT', status public.payment_status not null default 'pending', raw jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(provider, provider_event_id));
create index payment_tx_biz_idx on public.payment_transactions(business_id); create index payment_tx_appt_idx on public.payment_transactions(appointment_id);
create table public.payment_events (id uuid primary key default gen_random_uuid(), business_id uuid references public.businesses(id) on delete cascade, transaction_id uuid not null references public.payment_transactions(id) on delete cascade, event_type text not null, payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index payment_events_tx_idx on public.payment_events(transaction_id, created_at);
create table public.refunds (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, transaction_id uuid not null references public.payment_transactions(id), amount_minor bigint not null check (amount_minor > 0), reason text, provider_ref text, status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.subscription_plans (id uuid primary key default gen_random_uuid(), code text not null unique, name text not null, price_monthly_minor bigint not null default 0, price_yearly_minor bigint not null default 0, currency text not null default 'BDT', staff_limit int not null, monthly_booking_limit int not null, features jsonb not null default '{}'::jsonb, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, plan_id uuid not null references public.subscription_plans(id), status public.subscription_status not null default 'trialing', billing_period text not null default 'monthly' check (billing_period in ('monthly','yearly')), trial_ends_at timestamptz, current_period_start timestamptz, current_period_end timestamptz, grace_ends_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index subscriptions_biz_idx on public.subscriptions(business_id, status);
create table public.subscription_invoices (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, subscription_id uuid references public.subscriptions(id) on delete set null, invoice_number text not null unique, amount_minor bigint not null, currency text not null default 'BDT', status text not null default 'open', issued_at timestamptz not null default now(), paid_at timestamptz);
create table public.usage_records (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, metric text not null, quantity int not null default 1, period_start date not null default current_date, created_at timestamptz not null default now());
create index usage_biz_idx on public.usage_records(business_id, metric, period_start);
create trigger payment_tx_updated before update on public.payment_transactions for each row execute function public.set_updated_at();
create trigger subscriptions_updated before update on public.subscriptions for each row execute function public.set_updated_at();
